// Pseudo API for per-proof cost estimation
function estimateProofCost(securityLevel, proofSizeKB) {
  const cpuPerBit = securityLevel >= 128 ? 2 : 1;
  const energyPerOp = securityLevel >= 128 ? 0.5 : 0.2;
  return { cpuOps: proofSizeKB * 1000 * cpuPerBit, energyJ: proofSizeKB * 0.01 * energyPerOp };
}
```

